'use strict';

// MODULES //

var exp = require( '@stdlib/math/base/special/exp' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var normalCDF = require( '@stdlib/stats/base/dists/normal/cdf' ).factory


// MAIN //

/**
* Evaluates the cumulative distribution function (CDF) for a Wald distribution with mean `mu` and shape parameter `lambda` at a value `x`.
*
* @param {number} x - input value
* @param {number} mu - mean
* @param {NonNegativeNumber} lambda - shape parameter
* @returns {Probability} evaluated cumulative distribution function
*
* @example
* var y = cdf( 2.0, 1.0, 1.0 );
* // returns ~0.885
*
* @example
* var y = cdf( 0.5, 2.0, 3.0 );
* // returns ~0.055
*
* @example
* var y = cdf( NaN, 1.0, 1.0 );
* // returns NaN
*
* @example
* var y = cdf( 1.0, NaN, 1.0 );
* // returns NaN
*
* @example
* var y = cdf( 1.0, 1.0, NaN );
* // returns NaN
*
* @example
* // Non-positive mean:
* var y = cdf( 2.0, 0.0, 1.0 );
* // returns NaN
*
* @example
* // Negative shape parameter:
* var y = cdf( 2.0, 1.0, -1.0 );
* // returns NaN
*
* @example
* // Zero shape parameter (degenerate distribution):
* var y = cdf( 1.0, 1.0, 0.0 );
* // returns 1.0
*
* @example
* var y = cdf( 0.0, 1.0, 1.0 );
* // returns 0.0
*/
function cdf( x, mu, lambda ) {
	var C;
	var z;
	var t1;
	var t2;
	var phi;

	if (
		isnan( x ) ||
		isnan( mu ) ||
		isnan( lambda ) ||
		mu <= 0.0 ||
		lambda < 0.0
	) {
		return NaN;
	}
	if ( lambda == 0.0 ) {
		return ( x < mu ) ? 0.0 : 1.0;
	}
	if ( x <= 0.0 ) {
		return 0.0;
	}
	phi = normalCDF( 0.0, 1.0 );
	C = exp( 2.0 * lambda / mu );
	z = sqrt( lambda / x );
	t1 = phi( z * ( x / mu - 1.0 ) );
	t2 = C * phi( -z * ( x / mu + 1.0 ) );
	return t1 + t2;
}


// EXPORTS //

module.exports = cdf;
